17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	import java.util.Locale;
24	import java.util.regex.Pattern;
25	
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Syntactic email check: a non-empty local part, a single {@code @}, and a domain that contains
64	     * at least one dot. Whitespace and additional {@code @} characters are disallowed.
65	     */
66	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
67	
68	    private final ClinicService clinicService;
69	
70	    private final OwnerMapper ownerMapper;
71	
72	    private final PetMapper petMapper;
73	
74	    private final VisitMapper visitMapper;
75	
76	    public OwnerRestControllerV1(ClinicService clinicService,
77	                                 OwnerMapper ownerMapper,
78	                                 PetMapper petMapper,
79	                                 VisitMapper visitMapper) {
80	        this.clinicService = clinicService;
81	        this.ownerMapper = ownerMapper;
82	        this.petMapper = petMapper;
83	        this.visitMapper = visitMapper;
84	    }
85	
86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
114	        validateRequiredOwnerFields(ownerFieldsDto);
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
118	        owner.setTelephone(normalizedTelephone);
119	        owner.setEmail(normalizeEmail(owner.getEmail()));
120	        if (owner.getRegistrationDate() == null) {
121	            owner.setRegistrationDate(LocalDate.now());
122	        }
123	        rejectDuplicateTelephone(normalizedTelephone);
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
134	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
135	        if (currentOwner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        currentOwner.setAddress(ownerFieldsDto.getAddress());
139	        currentOwner.setCity(ownerFieldsDto.getCity());
140	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
141	        currentOwner.setLastName(ownerFieldsDto.getLastName());
142	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
143	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
144	        this.clinicService.saveOwner(currentOwner);
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Transactional
150	    @Override
151	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
152	        Owner owner = this.clinicService.findOwnerById(ownerId);
153	        if (owner == null) {
154	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
155	        }
156	        this.clinicService.deleteOwner(owner);
157	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Override
162	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
163	        Owner owner = this.clinicService.findOwnerById(ownerId);
164	        if (owner == null) {
165	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Pet pet = petMapper.toPet(petFieldsDto);
169	        owner.setId(ownerId);
170	        pet.setOwner(owner);
171	        pet.getType().setName(null);
172	        this.clinicService.savePet(pet);
173	        PetDto petDto = petMapper.toPetDto(pet);
174	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
175	            .buildAndExpand(pet.getId()).toUri());
176	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
177	    }
178	
179	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
180	    @Override
181	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
182	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
183	        if (currentOwner != null) {
184	            Pet currentPet = this.clinicService.findPetById(petId);
185	            if (currentPet != null) {
186	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
187	                currentPet.setName(petFieldsDto.getName());
188	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
189	                this.clinicService.savePet(currentPet);
190	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
191	            }
192	        }
193	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
199	        HttpHeaders headers = new HttpHeaders();
200	        Visit visit = visitMapper.toVisit(visitFieldsDto);
201	        Pet pet = new Pet();
202	        pet.setId(petId);
203	        visit.setPet(pet);
204	        this.clinicService.saveVisit(visit);
205	        VisitDto visitDto = visitMapper.toVisitDto(visit);
206	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
207	            .buildAndExpand(visit.getId()).toUri());
208	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
209	    }
210	
211	
212	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
213	    @Override
214	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
215	        Owner owner = this.clinicService.findOwnerById(ownerId);
216	        if (owner != null) {
217	            Pet pet = owner.getPet(petId);
218	            if (pet != null) {
219	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
220	            }
221	        }
222	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
223	    }
224	
225	    /**
226	     * Rejects an owner payload that is missing or blank in any of the required fields
227	     * (firstName, lastName, address, city, telephone). The bean-validation constraints on
228	     * {@link OwnerFieldsDto} already reject {@code null} values and most malformed input, but
229	     * a present-yet-blank {@code address} or {@code city} would otherwise slip through, so this
230	     * guard enforces the rule uniformly for every required field.
231	     *
232	     * @param ownerFieldsDto the submitted owner payload
233	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
234	     */
235	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
236	        List<String> invalidFields = new ArrayList<>();
237	        if (isBlank(ownerFieldsDto.getFirstName())) {
238	            invalidFields.add("firstName");
239	        }
240	        if (isBlank(ownerFieldsDto.getLastName())) {
241	            invalidFields.add("lastName");
242	        }
243	        if (isBlank(ownerFieldsDto.getAddress())) {
244	            invalidFields.add("address");
245	        }
246	        if (isBlank(ownerFieldsDto.getCity())) {
247	            invalidFields.add("city");
248	        }
249	        if (isBlank(ownerFieldsDto.getTelephone())) {
250	            invalidFields.add("telephone");
251	        }
252	        if (!invalidFields.isEmpty()) {
253	            throw new InvalidOwnerFieldsException(invalidFields);
254	        }
255	    }
256	
257	    private boolean isBlank(String value) {
258	        return value == null || value.isBlank();
259	    }
260	
261	    /**
262	     * Normalizes a submitted telephone number by removing every non-digit character and requires the
263	     * result to be exactly 10 digits. The normalized 10-digit value is what gets stored and returned.
264	     *
265	     * @param telephone the raw telephone value from the submitted owner payload
266	     * @return the normalized 10-digit telephone number
267	     * @throws InvalidOwnerFieldsException if the value is not exactly 10 digits after stripping
268	     */
269	    private String normalizeTelephone(String telephone) {
270	        String digits = telephone == null ? "" : telephone.replaceAll("\\D", "");
271	        if (digits.length() != 10) {
272	            throw new InvalidOwnerFieldsException(List.of("telephone"));
273	        }
274	        return digits;
275	    }
276	
277	    /**
278	     * Normalizes an optional owner email. A {@code null} value is left untouched (the field is optional).
279	     * When a value is present it must be a syntactically valid address (see {@link #EMAIL_PATTERN}); the
280	     * accepted value is trimmed and lower-cased before it is stored and returned.
281	     *
282	     * @param email the raw email value from the submitted owner payload, may be {@code null}
283	     * @return {@code null} if no email was supplied, otherwise the lower-cased email
284	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address
285	     */
286	    private String normalizeEmail(String email) {
287	        if (email == null) {
288	            return null;
289	        }
290	        String trimmed = email.strip();
291	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
292	            throw new InvalidOwnerFieldsException(List.of("email"));
293	        }
294	        return trimmed.toLowerCase(Locale.ROOT);
295	    }
296	
297	    /**
298	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
299	     * Existing owners' telephones are normalized (non-digit characters stripped) before comparison
300	     * so that differently-formatted representations of the same number are treated as duplicates.
301	     *
302	     * @param normalizedTelephone the normalized telephone of the owner being created
303	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same normalized telephone
304	     */
305	    private void rejectDuplicateTelephone(String normalizedTelephone) {
306	        boolean duplicate = this.clinicService.findAllOwners().stream()
307	            .map(Owner::getTelephone)
308	            .filter(telephone -> telephone != null)
309	            .map(telephone -> telephone.replaceAll("\\D", ""))
310	            .anyMatch(normalizedTelephone::equals);
311	        if (duplicate) {
312	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
313	        }
314	    }
315	}
